<?php get_header(); ?><div class="wrap layout no-sidebar"><main id="main"><?php while(have_posts()): the_post(); ?><article id="post-<?php the_ID(); ?>" <?php post_class(); ?>><h1><?php the_title(); ?></h1><?php if(has_post_thumbnail()): the_post_thumbnail('large',array('class'=>'post-cover')); endif; ?><div class="entry-content"><?php the_content(); wp_link_pages(); ?></div></article><?php if(comments_open() || get_comments_number()): comments_template(); endif; endwhile; ?></main></div><?php get_footer(); ?>
